CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password VARCHAR(120) NOT NULL,phone VARCHAR(20),city VARCHAR(80),blood_group VARCHAR(5),role VARCHAR(12) DEFAULT 'DONOR');
CREATE TABLE IF NOT EXISTS banks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120),city VARCHAR(80),address VARCHAR(180),phone VARCHAR(20));
CREATE TABLE IF NOT EXISTS inventory(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bank_id BIGINT REFERENCES banks(id),blood_group VARCHAR(5),component VARCHAR(40),units INT CHECK(units>=0),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(bank_id,blood_group,component));
CREATE TABLE IF NOT EXISTS appointments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),bank_id BIGINT REFERENCES banks(id),visit_date DATE,slot VARCHAR(20),status VARCHAR(15) DEFAULT 'CONFIRMED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),patient VARCHAR(100),blood_group VARCHAR(5),component VARCHAR(40),units INT CHECK(units>0),hospital VARCHAR(120),city VARCHAR(80),phone VARCHAR(20),needed DATE,status VARCHAR(15) DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS camps(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(130),city VARCHAR(80),venue VARCHAR(150),event_date DATE,organizer VARCHAR(100));
CREATE TABLE IF NOT EXISTS camp_signups(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),camp_id BIGINT REFERENCES camps(id),UNIQUE(user_id,camp_id));
